def pair(v):
 a,b=str(v).split('-');return float(a),float(b)
def wilson(m,n):
 z=1.96;p=m/n;den=1+z*z/n;center=(p+z*z/(2*n))/den;rad=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/den;return [round(center-rad,6),round(center+rad,6)]
