 for doc in s['players'].values():
  for id,rec in list(doc['inputs'].items()):
   if rec['status']!='unknown':continue
   kind=defs[id]['kind']
   if kind=='grade':value={'grade':70,'scale':scale}
   elif kind=='physical':
    if id=='P03':
     ht=doc['inputs']['P01']['value']['measurements'][0]['value'];span=doc['inputs']['P02']['value']['measurements'][0]['value'] if doc['inputs']['P02']['status']!='unknown' else 210;v=ht+70+.5*(span-ht);value=measure('hypothetical_standing_reach',round(v,3),'cm','unvalidated H1 dimensional fixture, not measured reach or shooting release point')
    elif id=='P10':value=measure('hypothetical_jump_gain',40,'cm','synthetic reference, no jump test performed')
    elif id in ['P05','P06','P07','P08','P09']:
     v,unit={'P05':(3,'m/s2'),'P06':(6,'m/s'),'P07':(2.5,'m/s'),'P08':(1000,'N'),'P09':(.5,'s')}[id];value=measure('synthetic_reference_capacity',v,unit,'DIMENSIONAL FIXTURE ONLY, not observed protocol')
    else:value={'measurements':[],'display_grade':{'grade':50,'scale':'synthetic_capacity_display_only'}}
   elif kind=='propensity':value={'probability':.5,'reference_conditions':'synthetic eligible opportunity, not observed intrinsic preference'}
   elif id=='T01':value={'reference_conditions':'synthetic all listed actions available','rows':[{'condition':'reference_opportunity','probabilities':{'shoot':.35,'drive':.25,'pass':.25,'post':.05,'reset':.1}}]}
   elif id=='T02':value={'reference_conditions':'synthetic location choice with both bins available','spatial_reference':'two_bin_experimental_2pt_3pt_v1','rows':[{'condition':'reference_opportunity','probabilities':{'two_point':.6,'three_point':.4}}]}
   elif id=='T03':value={'reference_conditions':'synthetic mutually selected shot-mode branch; labels can overlap in source data','rows':[{'condition':'reference_shot','probabilities':{'catch':.4,'pull_up':.3,'movement':.3}}]}
